// CI fixture: simulate values generated by Coolify without printing credentials.
import { randomBytes } from 'node:crypto';
import { writeFileSync } from 'node:fs';
const values={APP_ORIGIN:'http://127.0.0.1:3000',VOS_ADMIN_EMAIL:'ci@example.test',
  SERVICE_PASSWORD_DATABASE:randomBytes(16).toString('hex'),SERVICE_PASSWORD_OWNER:randomBytes(16).toString('hex'),
  SERVICE_REALBASE64_32_DATA:randomBytes(32).toString('base64'),SERVICE_BASE64_64_SESSION:randomBytes(48).toString('base64url'),
  VOS_TENANT_ID:'',VOS_CONTROL_PRIVATE_KEY:''};
writeFileSync('.env.ci',Object.entries(values).map(([k,v])=>`${k}=${v}`).join('\n')+'\n',{flag:'wx',mode:0o600});
